# shellcheck shell=bash disable=SC2034  # settings, read by lib/*.sh
# Defaults for orca-pr-review. Do not edit this file; it is replaced on update.
#
# Override any value in either of these (later wins):
#   $CONFIG_HOME/config.sh                   every repo
#   $CONFIG_HOME/repos/<owner>--<repo>.sh    one repo (written by `orca-pr-review init`)
#
# REPO_CONFIG_LOOKUP=0 (set in either file above) stops the plugin from reading
# .orca-pr-review/ from the repo at all: no GitHub lookup, and only the local
# personal overrides apply. Default 1.
REPO_CONFIG_LOOKUP=1
# where CONFIG_HOME is ${XDG_CONFIG_HOME:-~/.config}/orca-pr-review.

# --- Which PRs are reviewed -------------------------------------------------
RECENCY_DAYS=7            # only PRs updated within this many days
MAX_IN_FLIGHT=3           # concurrent reviews per repo
MAX_FILES=80              # skip PRs that change more files than this
STALE_HOURS=2             # a dispatched review older than this stops holding a slot
SKIP_OWN_PRS=1            # skip PRs authored by the gh user running this
SKIP_BOT_AUTHORS=0        # 1 skips PRs from bot accounts (dependabot, renovate, ...)
EXCLUDE_AUTHORS=""        # space-separated logins to skip
SKIP_STACKED=1            # skip PRs whose base is another open PR's head branch
# Untrusted PRs: a PR is trusted when its head branch is in this repo or its
# author is an OWNER, MEMBER or COLLABORATOR. Anything else (a fork PR from an
# outside contributor) is skipped by default, because review sessions can run
# the PR's tests and anything those load runs with your gh token and SSH keys.
# 1 reviews untrusted PRs too, but statically: the session is told not to run
# tests, builds, linters or package scripts from the checkout. Personal config
# only: a repo's pipeline.sh cannot set it.
REVIEW_UNTRUSTED_PRS=0

# --- Re-reviews -------------------------------------------------------------------
# A PR this plugin reviewed, whose review you submitted, is reviewed again when
# you are re-requested as a reviewer (right away) or when someone other than you
# pushes, replies on your threads, or comments on the PR, and then goes quiet for
# REREVIEW_QUIET_HOURS. This applies whatever your last verdict was, approvals included.
REREVIEW=1                # 0 turns re-reviews off
REREVIEW_QUIET_HOURS=1    # wait this long after the last activity (re-requests skip the wait)
MAX_REVIEW_ROUNDS=3       # total reviews per PR, the first one included

# --- When the scheduled dispatcher runs ---------------------------------------
# Local time. The Orca automation fires hourly on these days; dispatch.sh and
# backfill also refuse to start reviews outside the window.
WINDOW_DAYS="1-5"         # cron day-of-week field: 1-5 = Mon..Fri, * = every day
WINDOW_START_HOUR=9       # inclusive
WINDOW_END_HOUR=15        # inclusive: the last run starts at this hour

# --- Review stages ----------------------------------------------------------------
# Which parts of the review run. "validate" always runs whatever is listed here:
# it is the check on findings. A repo can change this in .orca-pr-review/pipeline.sh.
# Only the names concerns, review and validate are accepted.
DEFAULT_REVIEW_STAGES="concerns review validate"
REVIEW_STAGES="$DEFAULT_REVIEW_STAGES"
# Skills a repo's extra-skills.txt may name. Empty = any name with skill-name
# syntax ([a-z0-9:_-]). Space-separated, for example "security-review my:lint".
# Personal config only: a repo's pipeline.sh cannot set it.
EXTRA_SKILLS_ALLOW=""

# --- Review agent -------------------------------------------------------------
# The agent the per-PR review sessions run in. Only claude works today: the
# review skills need Claude Code's /code-review and the plugin's subagents.
# Set it in your personal config; a repo's pipeline.sh cannot change it.
REVIEW_AGENT=claude

# --- Dispatcher agent ---------------------------------------------------------
# The agent the scheduled automation starts. It only runs `dispatch` and reports
# the output, so any agent Orca can launch works; pick a cheap model.
# DISPATCHER_AGENT_ARGS empty = a cheap default for claude or codex, none for
# other agents. Changes reach an existing automation with update-automation.
DISPATCHER_AGENT=claude
DISPATCHER_AGENT_ARGS=""

# --- Models ---------------------------------------------------------------------
# The per-PR review session is routed: the high model when the PR touches a
# risky path or changes more than LOW_MODEL_MAX_LINES lines of non-test,
# non-generated code; the low model otherwise. The concerns and validator
# subagents use the model in their own definitions (sonnet).
REVIEW_MODEL_HIGH=opus
REVIEW_MODEL_LOW=sonnet
REVIEW_MODEL_OVERRIDE=""  # set to force one model for every PR
REVIEW_EFFORT=high
LOW_MODEL_MAX_LINES=250

# Extended regex over repo-relative paths. Empty = route by size only.
RISKY_PATHS=""
# Paths that do not count toward size or risk.
TEST_PATHS='(_test\.go$|/testdata/|(^|/)__tests__/|(^|/)tests?/|\.(test|spec)\.[cm]?[jt]sx?$|(^|/)test_[^/]*\.py$|_test\.py$|_spec\.rb$)'
GENERATED_PATHS='(\.lock$|-lock\.json$|^go\.sum$|/go\.sum$|zz_generated|\.pb\.go$|\.pb\.[a-z]+$|(^|/)vendor/|(^|/)node_modules/|\.snap$)'
